package dev.konqasasas.beat.spigot;
import dev.konqasasas.beat.BeatPlugin;import dev.konqasasas.beat.application.*;import dev.konqasasas.beat.configuration.ConfigurationFiles;import dev.konqasasas.beat.configuration.CompetitionSettingsService;import dev.konqasasas.beat.domain.state.TournamentState;import dev.konqasasas.beat.domain.ta.*;import dev.konqasasas.beat.map.*;import dev.konqasasas.beat.map.persistence.MapConfigurationService;import dev.konqasasas.beat.map.validation.MapValidationService;import dev.konqasasas.beat.persistence.PersistenceException;import dev.konqasasas.beat.roster.RosterService;import java.util.*;import java.util.logging.Level;import net.md_5.bungee.api.*;import net.md_5.bungee.api.chat.TextComponent;import org.bukkit.*;import org.bukkit.boss.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.scheduler.BukkitTask;import org.bukkit.util.Vector;
public final class TimeAttackController implements Listener,LiveCompetitionClock {private final BeatPlugin plugin;private final RosterService rosters;private final AdminAuthorizer admins;private final EventStateService states;private final MapConfigurationService maps;private final MapValidationService validation;private final TimeAttackResultService results;private final TimeAttackItem item;private final ConfigurationFiles configuration;private final CompetitionSettingsService settings;private final PlayerCollisionService collisions;private TimeAttackSession session;private BukkitTask task;private BossBar bar;private SharedRankingBoard rankingBoard;private long tick;private long totalTicks;private int countdown;private boolean rankingDirty;private List<Integer> eliminationTicks=List.of();private List<Integer> survivorCounts=List.of();private final Set<Integer> processedEliminations=new HashSet<>();private final Map<UUID,Boolean> inside=new HashMap<>();private final Map<UUID,String> renderedTabRows=new HashMap<>();private final ActionBarFeedbackState feedback=new ActionBarFeedbackState();
public TimeAttackController(BeatPlugin p,RosterService r,AdminAuthorizer admins,EventStateService s,MapConfigurationService m,MapValidationService v,TimeAttackResultService results,ConfigurationFiles configuration,CompetitionSettingsService settings,PlayerCollisionService collisions){plugin=p;rosters=r;this.admins=admins;states=s;maps=m;validation=v;this.results=results;this.configuration=configuration;this.settings=settings;this.collisions=collisions;item=new TimeAttackItem(p);}public void start()throws PersistenceException{if(session!=null)throw new IllegalStateException("TAは進行中です");if(states.current().tournamentState()!=TournamentState.HIGH_FINISHED&&states.current().tournamentState()!=TournamentState.TA_READY)throw new IllegalStateException("TAを開始できる状態ではありません");var report=validation.validateTimeAttack(maps.timeAttack());if(!report.passed())throw new IllegalStateException("TAマップ検証ERROR: "+report.errorCount());var schedule=settings.current();totalTicks=schedule.timeAttackRunningTicks();eliminationTicks=schedule.timeAttackEliminationTicks();survivorCounts=schedule.timeAttackSurvivorCounts();processedEliminations.clear();if(states.current().tournamentState()==TournamentState.HIGH_FINISHED)states.transitionTo(TournamentState.TA_READY);states.transitionTo(TournamentState.TA_COUNTDOWN);Map<UUID,String> names=new LinkedHashMap<>();rosters.current().participants().forEach((id,x)->names.put(id,states.tournamentName(id).orElse(x.mcid())));session=new TimeAttackSession(names);rankingBoard=new SharedRankingBoard("beat_ta",configuration.message("ui.scoreboard.time-attack-title","TIME ATTACK"),collisions);renderedTabRows.clear();countdown=(int)schedule.startCountdownTicks();tick=0;rankingDirty=true;ensureBar();forPlayers(this::prepare);forAdminObservers(this::prepareAdmin);announce(countdown/20);task=Bukkit.getScheduler().runTaskTimer(plugin,this::runTick,1,1);}
@EventHandler public void use(PlayerInteractEvent e){if(!item.is(e.getItem()))return;e.setCancelled(true);if(session==null||countdown>0||!session.contains(e.getPlayer().getUniqueId())||!session.active(e.getPlayer().getUniqueId()))return;Player p=e.getPlayer();MapLocation l=loc(p);if(maps.timeAttack().goal().isSteppedOnBy(l))goal(p);session.markRestarted(p.getUniqueId());p.setVelocity(new Vector());tp(p,maps.timeAttack().restart());inside.put(p.getUniqueId(),false);}
@EventHandler public void join(PlayerJoinEvent e){if(session==null)return;Player joined=e.getPlayer();if(!session.contains(joined.getUniqueId())){if(admins.isAdmin(joined.getUniqueId()))Bukkit.getScheduler().runTask(plugin,()->prepareAdmin(joined));return;}inside.put(joined.getUniqueId(),false);Bukkit.getScheduler().runTask(plugin,()->{Player p=e.getPlayer();if(session.active(p.getUniqueId())){CompetitionPlayerState.normalize(p);item.give(p);bar.addPlayer(p);rankingBoard.show(p);rankingDirty=true;return;}if(!eliminationTicks.isEmpty()&&tick>=eliminationTicks.getFirst()){p.setGameMode(GameMode.SPECTATOR);rankingDirty=true;return;}session.activate(p.getUniqueId());CompetitionPlayerState.normalize(p);item.give(p);bar.addPlayer(p);rankingBoard.show(p);tp(p,maps.timeAttack().restart());rankingDirty=true;});}
@EventHandler(priority=EventPriority.HIGHEST)public void move(PlayerMoveEvent e){if(session!=null&&countdown>0&&session.contains(e.getPlayer().getUniqueId())&&e.getTo()!=null){var f=e.getFrom();var t=e.getTo();t.setX(f.getX());t.setY(f.getY());t.setZ(f.getZ());e.setTo(t);}}
private void runTick(){try{if(countdown>0){countdown--;if(countdown==0){states.transitionTo(TournamentState.TA_RUNNING);Bukkit.broadcastMessage(configuration.message("notifications.time-attack.started","[BEAT] TA競技開始！"));forPlayers(p->session.activate(p.getUniqueId()));forAudience(p->playConfigured(p,"sounds.competition-start",Sound.BLOCK_NOTE_BLOCK_BELL,1F,1.2F));rankingDirty=true;updateRankingIfDirty();}else if(countdown%20==0)announce(countdown/20);return;}long previous=tick++;scan();cutoffs(previous,tick);announceTimeLimit();updateRankingIfDirty();ui();if(tick>=totalTicks)finish();}catch(Exception e){plugin.getLogger().log(Level.SEVERE,"TA進行を停止しました",e);shutdown();}}
private void scan(){for(Player p:Bukkit.getOnlinePlayers()){UUID id=p.getUniqueId();if(!session.contains(id)||!session.active(id))continue;MapLocation l=loc(p);boolean now=maps.timeAttack().start().isSteppedOnBy(l),was=inside.getOrDefault(id,false);if(session.enterStart(id,was,now,true,tick))playConfigured(p,"sounds.ta-start",Sound.BLOCK_NOTE_BLOCK_PLING,0.8F,1.2F);inside.put(id,now);for(var s:maps.timeAttack().splits().entrySet())if(s.getValue().isSteppedOnBy(l)){var time=session.reachSplit(id,s.getKey(),tick);if(time.isPresent()){var record=session.record(id);var pb=s.getKey()==1?record.personalBestSplit1Ticks():s.getKey()==2?record.personalBestSplit2Ticks():java.util.OptionalLong.empty();notice(p,configuration.message("notifications.time-attack.split","Split {split} {time} ｜ PB {pb}",Map.of("split",s.getKey(),"time",fmt(time.getAsLong()),"pb",pb.isPresent()?fmt(pb.getAsLong()):"--.--")));playConfigured(p,"sounds.ta-split",Sound.BLOCK_NOTE_BLOCK_PLING,0.8F,1.5F);}}if(maps.timeAttack().goal().isSteppedOnBy(l))goal(p);}}
private void goal(Player p){var g=session.reachGoal(p.getUniqueId(),tick);if(!g.valid())return;String soundPath;Sound fallback;float volume;if(g.personalBest()){rankingDirty=true;notice(p,configuration.message("notifications.time-attack.personal-best","PB更新! {time} ｜ #{rank}",Map.of("time",fmt(g.elapsedTicks()),"rank",g.currentRank())));soundPath="sounds.ta-personal-best";fallback=Sound.ENTITY_PLAYER_LEVELUP;volume=1F;if(g.rankChanged())Bukkit.broadcastMessage(configuration.message("notifications.time-attack.rank-update","[BEAT] {player} が更新: {time} (#{rank})",Map.of("player",session.competitor(p.getUniqueId()).tournamentName(),"time",fmt(g.elapsedTicks()),"rank",g.currentRank())));}else{notice(p,configuration.message("notifications.time-attack.run-finished","Time {time} ｜ PB {pb} ｜ +{difference}",Map.of("time",fmt(g.elapsedTicks()),"pb",fmt(g.currentBest()),"difference",fmt(g.elapsedTicks()-g.currentBest()))));soundPath="sounds.ta-finished";fallback=Sound.BLOCK_NOTE_BLOCK_CHIME;volume=0.9F;}p.setVelocity(new Vector());tp(p,maps.timeAttack().restart());inside.put(p.getUniqueId(),false);Bukkit.getScheduler().runTask(plugin,()->{if(p.isOnline())playConfigured(p,soundPath,fallback,volume,1F);});}
private void cutoffs(long previous,long current){for(int i=0;i<Math.min(eliminationTicks.size(),survivorCounts.size());i++){long boundary=eliminationTicks.get(i),rem=boundary-current;int eliminatedFrom=survivorCounts.get(i)+1;if(rem>=20&&rem<=200&&rem%20==0)forAudience(p->{p.sendMessage(configuration.message("notifications.time-attack.elimination-warning","[BEAT] {rank}位以下脱落まで... {seconds}",Map.of("rank",eliminatedFrom,"seconds",rem/20)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});if(previous<boundary&&current>=boundary&&processedEliminations.add(i)){Bukkit.broadcastMessage(configuration.message("notifications.time-attack.elimination","[BEAT] {rank}位以下脱落！",Map.of("rank",eliminatedFrom)));forAudience(p->playConfigured(p,"sounds.elimination",Sound.BLOCK_NOTE_BLOCK_BASS,1F,0.7F));List<UUID> eliminated=session.eliminateToTop(survivorCounts.get(i));rankingDirty=true;for(UUID id:eliminated){Player p=Bukkit.getPlayer(id);if(p!=null){p.setGameMode(GameMode.SPECTATOR);item.remove(p);p.sendMessage(configuration.message("notifications.time-attack.eliminated","[BEAT] 脱落しました。最終記録: {time} (#{rank})",Map.of("time",session.record(id).hasPersonalBest()?fmt(session.record(id).personalBestTicks().orElseThrow()):"--.--","rank",session.rank(id))));}}}}}

private void announceTimeLimit(){long remaining=totalTicks-tick;if(remaining>0&&remaining<=200&&remaining%20==0)forAudience(p->{p.sendMessage(configuration.message("notifications.time-attack.time-limit-countdown","[BEAT] 制限時間終了まで... {seconds}",Map.of("seconds",remaining/20)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});else if(remaining==0)forAudience(p->{p.sendMessage(configuration.message("notifications.time-attack.time-limit-ended","[BEAT] 制限時間終了！"));playConfigured(p,"sounds.time-limit-end",Sound.BLOCK_NOTE_BLOCK_BASS,1,0.5F);});}
private void ui(){long total=totalTicks;if(tick%configuration.configInt("ui-update-ticks.boss-bar",10,1,1200)==0){bar.setProgress(Math.max(0,(double)(total-tick)/total));Long next=eliminationTicks.stream().mapToLong(Integer::longValue).filter(x->x>tick).boxed().findFirst().orElse(null);bar.setTitle(configuration.message("ui.bossbar.competition-time","残り時間 {remaining} ｜ 次の脱落 {next}",Map.of("remaining",fmtClock(total-tick),"next",next==null?"--:--":fmtClock(next-tick))));}if(tick%configuration.configInt("ui-update-ticks.action-bar",10,1,1200)!=0)return;var ranking=session.rankings();Map<UUID,Integer> ranks=new HashMap<>();ranking.forEach(e->ranks.put(e.competitor().uuid(),e.rank()));String border=border(ranking);for(Player p:Bukkit.getOnlinePlayers())if(session.contains(p.getUniqueId())){UUID id=p.getUniqueId();String notification=feedback.activeMessage(id,tick);if(notification!=null){action(p,notification);continue;}String pb=session.record(id).hasPersonalBest()?fmt(session.record(id).personalBestTicks().orElseThrow()):"--.--";String rank=session.record(id).hasPersonalBest()?"%02d".formatted(ranks.get(id)):"--";Map<String,Object> values=Map.of("time",fmt(session.displayedElapsed(id,tick)),"pb",pb,"rank",rank,"border",border);String status=configuration.message("ui.time-attack.status","Time {time} ｜ PB {pb} ｜ #{rank}",values)+configuration.message("ui.time-attack.border"," ｜ Border {border}",values);action(p,status);}}
private String border(List<dev.konqasasas.beat.domain.ranking.RankedEntry<TimeAttackRecord>> ranking){return TimeAttackBorderDisplay.format(tick,eliminationTicks,survivorCounts,ranking);}
private void updateRankingIfDirty(){if(!rankingDirty)return;rankingDirty=false;updateRanking();}
private void updateRanking(){var ranking=session.rankings();rankingBoard.update(ranking.stream().limit(10).map(e->{String time=e.record().hasPersonalBest()?fmt(e.record().personalBestTicks().orElseThrow()):"--.--";return configuration.message("ui.scoreboard.time-attack-row","#{rank} {time} {player}",Map.of("rank","%02d".formatted(e.rank()),"time",time,"player",e.competitor().tournamentName()));}).toList());forAudience(rankingBoard::show);for(var e:ranking){Player p=Bukkit.getPlayer(e.competitor().uuid());if(p!=null){String time=e.record().hasPersonalBest()?fmt(e.record().personalBestTicks().orElseThrow()):"--.--";String row=configuration.message("ui.tab.time-attack-row","#{rank} {time} {player}",Map.of("rank","%02d".formatted(e.rank()),"time",time,"player",p.getName()));if(!row.equals(renderedTabRows.put(p.getUniqueId(),row))){p.setPlayerListOrder(e.rank());p.setPlayerListName(row);}}}}
@Override public synchronized Optional<LiveCompetitionClock.Snapshot> liveClock(){return session==null?Optional.empty():Optional.of(new LiveCompetitionClock.Snapshot(countdown>0?"TA_COUNTDOWN":"TA_RUNNING",countdown>0?settings.current().startCountdownTicks()-countdown:tick,countdown>0?settings.current().startCountdownTicks():totalTicks,countdown>0?List.of(settings.current().startCountdownTicks()):eliminationTicks.stream().map(Integer::longValue).toList()));}
@Override public synchronized void debugSetElapsedTick(long target){if(session==null)throw new IllegalStateException("TAは進行中ではありません");if(countdown>0){long elapsed=settings.current().startCountdownTicks()-countdown;if(target<elapsed||target>=settings.current().startCountdownTicks())throw new IllegalArgumentException("指定時刻が範囲外です");countdown=(int)(settings.current().startCountdownTicks()-target);return;}if(target<tick||target>=totalTicks)throw new IllegalArgumentException("指定時刻が範囲外です");long previous=tick;tick=target;cutoffs(previous,tick);rankingDirty=true;ui();}
public void forceFinish()throws PersistenceException{if(session==null)throw new IllegalStateException("TA競技は実行中ではありません");finish();}
private void finish()throws PersistenceException{session.finish();results.saveFinal(session);states.transitionTo(TournamentState.TA_FINISHED);forAudience(p->{p.setVelocity(new Vector());item.remove(p);tp(p,maps.timeAttack().end());});Bukkit.broadcastMessage(configuration.message("notifications.time-attack.finished","[BEAT] TAが終了し結果を確定しました。"));shutdown();}
private void prepare(Player p){CompetitionPlayerState.normalize(p);tp(p,maps.timeAttack().restart());item.give(p);ensureBar();bar.addPlayer(p);rankingBoard.show(p);inside.put(p.getUniqueId(),false);}private void prepareAdmin(Player p){if(!p.isOnline()||session==null||session.contains(p.getUniqueId())||!admins.isAdmin(p.getUniqueId()))return;tp(p,maps.timeAttack().restart());ensureBar();bar.addPlayer(p);rankingBoard.show(p);}private void ensureBar(){if(bar==null)bar=Bukkit.createBossBar(configuration.message("ui.bossbar.time-attack-title","TIME ATTACK"),configuration.barColor("boss-bars.time-attack",BarColor.BLUE),configuration.barStyle("boss-bars.time-attack",BarStyle.SOLID));}private void announce(int n){forAudience(p->{p.sendMessage(configuration.message("notifications.time-attack.countdown","[BEAT] 競技開始まで... {seconds}",Map.of("seconds",n)));playConfigured(p,"sounds.countdown",Sound.BLOCK_NOTE_BLOCK_HAT,1,1);});}private void playConfigured(Player p,String path,Sound fallback,float volume,float pitch){p.playSound(p.getLocation(),configuration.sound(path,fallback),configuration.soundVolume(path,volume),configuration.soundPitch(path,pitch));}private void forPlayers(java.util.function.Consumer<Player> c){for(Player p:Bukkit.getOnlinePlayers())if(session!=null&&session.contains(p.getUniqueId()))c.accept(p);}private void forAdminObservers(java.util.function.Consumer<Player> c){for(Player p:Bukkit.getOnlinePlayers())if(session!=null&&!session.contains(p.getUniqueId())&&admins.isAdmin(p.getUniqueId()))c.accept(p);}private void forAudience(java.util.function.Consumer<Player> c){for(Player p:Bukkit.getOnlinePlayers())if(session!=null&&(session.contains(p.getUniqueId())||admins.isAdmin(p.getUniqueId())))c.accept(p);}public void shutdown(){if(task!=null)task.cancel();task=null;if(bar!=null)bar.removeAll();bar=null;if(rankingBoard!=null){rankingBoard.clear();rankingBoard.hideAll();}if(session!=null)forPlayers(p->{item.remove(p);p.setPlayerListOrder(0);p.setPlayerListName(p.getName());});session=null;rankingBoard=null;renderedTabRows.clear();inside.clear();feedback.clear();}private void notice(Player p,String s){String notification=configuration.actionBarNotification(s);feedback.show(p.getUniqueId(),notification,tick+configuration.styleInt("display-ticks.feedback",20,1,1200));action(p,notification);}private static void action(Player p,String s){p.spigot().sendMessage(ChatMessageType.ACTION_BAR,TextComponent.fromLegacy(s));}private static String fmt(long t){return "%02d.%02d".formatted(t/20,(t%20)*5);}private static String fmt(Long t){return t==null?"--.--":fmt(t.longValue());}private static String fmtClock(long t){long s=Math.max(0,(t+19)/20);return "%02d:%02d".formatted(s/60,s%60);}private static MapLocation loc(Player p){var l=p.getLocation();return new MapLocation(l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());}private static void tp(Player p,MapLocation l){World w=Bukkit.getWorld(l.world());if(w!=null)p.teleport(new Location(w,l.x(),l.y(),l.z(),l.yaw(),l.pitch()));}}
